const texto = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}';

// Limpia los marcadores de markdown que Gemini a veces agrega
const textoLimpio = texto.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();

try {
  const parsed = JSON.parse(textoLimpio);
  return [{ json: parsed }];
} catch (e) {
  return [{ json: { parametros_faltantes: ['ERROR_PARSEO_JSON'], error_original: texto } }];
}

