const proyecto = $('Airtable - Crear Proyecto').item.json.fields;
const parametros = $('Code - Parsear Respuesta Parametrizador').first().json;
const resultado = $('Code Python - Ejecutar Calculo Estructural').first().json;
const auditoria = $('Code - Parsear Respuesta Auditor').first().json;

const reporte = `
MEMORIA DE CALCULO ESTRUCTURAL
Cliente: ${proyecto.Cliente}
Elemento: ${proyecto.Tipo_Elemento}
Fecha: ${new Date().toLocaleDateString('es-AR')}

DATOS DE ENTRADA
${proyecto.Instrucciones_Diseno}

PARAMETROS UTILIZADOS
Carga permanente: ${parametros.cargas.permanente_kNm} kN/m
Sobrecarga: ${parametros.cargas.sobrecarga_kNm} kN/m
Geometria: ${parametros.geometria.ancho_cm}cm x ${parametros.geometria.alto_cm}cm, luz ${parametros.geometria.luz_m}m
Material: f'c = ${parametros.material.fc_MPa} MPa, fy = ${parametros.material.fy_MPa} MPa

RESULTADOS DEL CALCULO
Momento actuante mayorado (Mu): ${resultado.Mu_kNm} kN.m
Armadura requerida: ${resultado.As_requerida_cm2} cm2
Coeficiente de utilizacion: ${resultado.coeficiente_utilizacion}

AUDITORIA DE COHERENCIA
Conforme: ${auditoria.conforme ? 'SI' : 'CON OBSERVACIONES'}
${auditoria.motivo}
Fuentes citadas: ${auditoria.fuentes_citadas.join(', ')}

Aprobado por: ${proyecto.Ingeniero_Responsable}

---
NOTA: Este calculo fue generado con asistencia de IA y debe ser revisado y
validado por un ingeniero matriculado antes de su uso en obra.
`;

return [{ json: { reporte_final: reporte, ...proyecto } }];

const matches = $json.matches || [];
const contexto = matches.map(m => m.fuente + ': ' + m.texto).join(' | ');
const instrucciones = $('Code - Parsear Normativa Detectada').first().json.proyecto.Instrucciones_Diseno;

const promptText = `Sistema: estructura parametros de calculo SOLO con base en el contexto normativo. Devolve JSON con EXACTAMENTE esta forma, con valores numericos reales extraidos de las instrucciones (nunca texto descriptivo en los campos numericos):

{
  "tipo_elemento": "string",
  "cargas": { "permanente_kNm": number, "sobrecarga_kNm": number, "sismo_kNm": number o null },
  "geometria": { "ancho_cm": number, "alto_cm": number, "luz_m": number },
  "material": { "fc_MPa": number, "fy_MPa": number },
  "factores_seguridad": { "phi_flexion": number },
  "fuentes_citadas": ["string"],
  "parametros_faltantes": ["string"]
}

Si algun dato numerico no esta en las instrucciones, ponelo en parametros_faltantes y dejalo como null en el campo correspondiente. NO inventes valores, y NO devuelvas texto descriptivo en lugar de numeros.

Contexto normativo: ${contexto}
Instrucciones: ${instrucciones}`;

return [{
  json: {
    contents: [{ parts: [{ text: promptText }] }],
    generationConfig: { maxOutputTokens: 800, temperature: 0.1 }
  }
}];

